#include <iostream>
using namespace std;

int main() {
    int n, m, a, b;
    cin >> n >> m >> a >> b;
    int tickets = n * a;                      // лише квитки
    int mixed = (n / m) * b + (n % m) * a;    // проїзні + квитки на решту
    int passes = (n / m) * b;                 // лише проїзні
    if (n % m != 0) {
        passes += b;
    }
    int best = tickets;
    if (mixed < best) best = mixed;
    if (passes < best) best = passes;
    cout << best << "\n";
    return 0;
}

